/// <reference types="vite/client" />
/* 
  السطر المرجعي أعلاه يقوم بتضمين كافة التعريفات والأنواع الخاصة بأداة البناء Vite
  مما يسمح للتطبيق بالتعامل مع متغيرات البيئة (import.meta.env) وخصائص التطوير المباشر
*/

/* ==========================================================================
   تعريف موديولات استيراد الصور بتنسيق JPG
   يسمح لمحرر الكود و TypeScript بقبول استيراد صور .jpg واستخدامها كمسارات نصية
   ========================================================================== */
declare module "*.jpg" {
  const src: string;
  export default src;
}

/* ==========================================================================
   تعريف موديولات استيراد الصور بتنسيق PNG
   يسمح لمحرر الكود و TypeScript بقبول استيراد صور .png (مثل الشعار) كمسارات نصية
   ========================================================================== */
declare module "*.png" {
  const src: string;
  export default src;
}